<template><span><el-button data-testid="manage-content-scopes" @click="open">Content Scopes</el-button><el-dialog title="Content Scopes" :visible.sync="visible" width="850px" :close-on-click-modal="false"><p class="field-help">Each content item belongs to one Scope. Suits select explicit scopes. A new scope is not automatically included in an existing Suit.</p><el-alert v-if="error" type="error" :title="error" :closable="false"/><el-table v-loading="loading" :data="scopes" border><el-table-column prop="entitlementCode" label="Content Entitlement" min-width="190"/><el-table-column prop="name" label="Scope" min-width="160"/><el-table-column prop="code" label="Code" min-width="140"/><el-table-column prop="status" label="Status" width="100"/><el-table-column label="Action" width="80"><template slot-scope="s"><el-button type="text" @click="edit(s.row)">Edit</el-button></template></el-table-column></el-table><el-button style="margin-top:12px" @click="edit(null)">Add Scope</el-button><el-form v-if="form" label-width="150px" style="margin-top:20px" :disabled="busy"><el-form-item label="Content Entitlement"><el-select v-model="form.entitlementCode" :disabled="!!original"><el-option v-for="item in contentItems" :key="item.code" :label="item.name" :value="item.code"/></el-select></el-form-item><el-form-item label="Scope Code"><el-input v-model.trim="form.code" :disabled="!!original" placeholder="e.g. strength_series"/></el-form-item><el-form-item label="Scope Name"><el-input v-model.trim="form.name" maxlength="80"/></el-form-item><el-form-item label="Status"><el-select v-model="form.status"><el-option label="Active" value="active"/><el-option label="Disabled" value="disabled"/></el-select><p class="field-help">Disabled stops new selection. It does not remove historical authorization or change existing content mappings.</p></el-form-item><el-form-item><el-button type="primary" :loading="busy" @click="save">Save Scope</el-button><el-button @click="form=null">Cancel edit</el-button></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">Close</el-button></span></el-dialog></span></template>
<script>
import {getCatalog} from '@/api/commercialization'
import {getContentScopes,createContentScope,saveContentScope} from '@/api/commerce'
export default{data(){return{visible:false,loading:false,busy:false,error:'',scopes:[],catalog:[],form:null,original:null}},computed:{contentItems(){return this.catalog.filter(item=>item.type==='content_access')}},methods:{async open(){this.visible=true;this.form=null;this.loading=true;this.error='';try{const [scopes,catalog]=await Promise.all([getContentScopes(),getCatalog()]);this.scopes=scopes;this.catalog=catalog}catch(e){this.error=e.message}finally{this.loading=false}},edit(scope){this.original=scope;this.form=scope?{...scope}:{entitlementCode:'course_access',code:'',name:'',status:'active'}},async save(){this.busy=true;this.error='';try{if(this.original)await saveContentScope(this.form,this.original.revision);else await createContentScope(this.form);this.scopes=await getContentScopes();this.catalog=await getCatalog();this.form=null;this.$message.success('Content scope saved. Existing Suit selections are unchanged.');this.$emit('changed')}catch(e){this.error=e.message}finally{this.busy=false}}}}
</script>
